def transform(grid):
    """Fill bounding boxes of components of size >=3 with their color, then set unreachable non-bg cells to bg."""
    H,W=len(grid),len(grid[0])
    bg=Counter(cell for row in grid for cell in row).most_common(1)[0][0]

    seen=[[False]*W for _ in range(H)]
    res=[list(row) for row in grid]  # Make a copy
    inr=[[False]*W for _ in range(H)]

    # Find and expand components
    for i in range(H):
        for j in range(W):
            if seen[i][j] or grid[i][j]==bg: 
                continue
            c=grid[i][j]
            q=deque([(i,j)])
            seen[i][j]=True
            comp=[]

            while q:
                y,x=q.popleft()
                comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and grid[ny][nx]==c:
                        seen[ny][nx]=True
                        q.append((ny,nx))

            # If component has at least 3 cells, fill its bounding box
            if len(comp)>=3:
                ys=[p[0] for p in comp]
                xs=[p[1] for p in comp]
                for y in range(min(ys), max(ys)+1):
                    for x in range(min(xs), max(xs)+1):
                        res[y][x]=c
                        inr[y][x]=True

    # Set any non-visited non-bg cells to background
    for i in range(H):
        for j in range(W):
            if not inr[i][j] and res[i][j]!=bg:
                res[i][j]=bg

    return res

