def bbox_fill(grid, H, W):
    colors = Counter(cell for row in grid for cell in row)
    bg = colors.most_common(1)[0][0]

    seen = [[False] * W for _ in range(H)]
    res = [list(row) for row in grid]

    for i in range(H):
        for j in range(W):
            if grid[i][j] == bg or seen[i][j]:
                continue

            color = grid[i][j]
            q = deque([(i, j)])
            seen[i][j] = True
            component_cells = [(i, j)]

            while q:
                r, c = q.popleft()
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if not seen[nr][nc] and grid[nr][nc] == color:
